/* steps of a map scene = its steps list */
SV1.scenes.forEach(s => { if (s.type === 'map') s.steps = s.st.length; });
/* 22 Oct 15:22 Amr: «كل محتويات السلايد يحصل فيها الانميشن من اول كليك ماعدا في السلايدات اللي بتشرح الخرايط على مراحل»:
   every scene but the maps is ONE click; its builds play by themselves, one after another (sv-engine.js «builds») */
SV1.scenes.forEach(s => { if (s.type !== 'map' && (s.steps || 1) > 1) { s.builds = s.steps; s.steps = 1; } });
